SELECT DISTINCT h.id AS id_house, h.id_address_data, o.id AS id_offer, o.id_firestore, o.id_sales_flow, sf.id_buyer, sf.id_seller, CAST('{year}-{month}-{day}' AS DATE) AS dt_load, STRUCT(year AS year) AS year, STRUCT(month AS month) AS month, STRUCT(day AS day) AS day FROM datalake_sales_flow_clean.house_aud AS h JOIN datalake_sales_flow_clean.sales_flow_aud AS sf ON sf.id_house = h.id JOIN datalake_sales_flow_clean.offer AS o ON o.id_sales_flow = sf.id WHERE CAST(sf.ts_created AS DATE) = CAST('{year}-{month}-{day}' AS DATE) OR CAST(o.ts_created AS DATE) = CAST('{year}-{month}-{day}' AS DATE) OR (sf.year = STRUCT(year AS year) AND sf.month = STRUCT(month AS month) AND sf.day = STRUCT(day AS day) AND (sf.mod_id_buyer IS TRUE OR sf.mod_id_seller IS TRUE)) OR (h.year = STRUCT(year AS year) AND h.month = STRUCT(month AS month) AND h.day = STRUCT(day AS day) AND h.mod_id_address_data IS TRUE)